# filename: scripts/deploy-observability.sh
# Code Generated by Sidekick is for learning and experimentation purposes only.
#!/usr/bin/env bash
set -euo pipefail

CLUSTER_NAME="${1:?Usage: deploy-observability.sh <cluster-name> <region>}"
REGION="${2:?Usage: deploy-observability.sh <cluster-name> <region>}"
OBS_NAMESPACE="ibts-observability"
GRAFANA_PASSWORD="${TF_VAR_grafana_admin_password:-ibts-grafana-dev}"
KARPENTER_VERSION="${KARPENTER_VERSION:-1.0.8}"

echo "==> Cluster : $CLUSTER_NAME"
echo "==> Region  : $REGION"

echo "==> Configuring kubectl"
aws eks update-kubeconfig --region "$REGION" --name "$CLUSTER_NAME"

echo "==> Verifying cluster connectivity"
kubectl get nodes --no-headers | awk '{print "  node:", $1, $2}'

echo "==> Node labels (checking for purpose label)"
kubectl get nodes --show-labels | grep -o 'purpose=[^ ,]*' \
  || echo "  no purpose label found on any node"

echo "==> Adding Helm repos"
helm repo add prometheus-community https://prometheus-community.github.io/helm-charts
helm repo add elastic               https://helm.elastic.co
helm repo add open-telemetry        https://open-telemetry.github.io/opentelemetry-helm-charts
helm repo add jaegertracing         https://jaegertracing.github.io/helm-charts
helm repo add fluent                https://fluent.github.io/helm-charts
helm repo update
echo "  Repos updated"

# ════════════════════════════════════════
# HELPERS
# ════════════════════════════════════════
install_or_upgrade() {
  local release=$1
  local namespace=$2
  local chart=$3
  shift 3

  local status
  status=$(helm status "$release" -n "$namespace" --output json 2>/dev/null \
    | python3 -c "import sys,json; print(json.load(sys.stdin)['info']['status'])" \
    2>/dev/null || echo "not-found")

  if [[ "$status" != "not-found" ]]; then
    echo "  Uninstalling existing $release (status: $status) for clean install"
    helm uninstall "$release" -n "$namespace" --ignore-not-found
    sleep 5
  fi

  echo "  Installing $release"
  helm install "$release" "$chart" -n "$namespace" "$@"
}

wait_for_pods() {
  local namespace=$1
  local description=$2
  local timeout_seconds=${3:-900}
  local elapsed=0
  local interval=30

  echo "  Polling $description pods in $namespace (timeout ${timeout_seconds}s)"

  while [[ $elapsed -lt $timeout_seconds ]]; do
    local total ready pending failed
    total=$(kubectl get pods -n "$namespace" \
      --no-headers 2>/dev/null | wc -l | tr -d ' ')
    ready=$(kubectl get pods -n "$namespace" \
      --no-headers 2>/dev/null \
      | awk '$2~/^([0-9]+)\/\1$/ && $3=="Running"' \
      | wc -l | tr -d ' ')
    pending=$(kubectl get pods -n "$namespace" \
      --no-headers 2>/dev/null \
      | awk '$3=="Pending"' | wc -l | tr -d ' ')
    failed=$(kubectl get pods -n "$namespace" \
      --no-headers 2>/dev/null \
      | awk '$3~/Error|CrashLoop|OOMKilled/' \
      | wc -l | tr -d ' ')

    echo "  [${elapsed}s] total=${total} ready=${ready} pending=${pending} failed=${failed}"

    if [[ "$total" -gt "0" && "$ready" -eq "$total" && "$failed" -eq "0" ]]; then
      echo "  ✅ All $description pods Ready"
      return 0
    fi

    if (( elapsed % 60 == 0 && elapsed > 0 )); then
      echo "  --- pod list ---"
      kubectl get pods -n "$namespace" --no-headers 2>/dev/null || true
      echo "  --- pvc status ---"
      kubectl get pvc  -n "$namespace" --no-headers 2>/dev/null || true
      echo "  --- scheduling events ---"
      kubectl get events -n "$namespace" \
        --field-selector reason=FailedScheduling \
        --sort-by='.lastTimestamp' 2>/dev/null | tail -8 || true
      echo "  --- karpenter nodeclaims ---"
      kubectl get nodeclaims 2>/dev/null | head -10 || true
      echo "  --- karpenter logs ---"
      kubectl logs -n kube-system \
        -l app.kubernetes.io/name=karpenter \
        --tail=8 2>/dev/null || true
    fi

    sleep $interval
    elapsed=$(( elapsed + interval ))
  done

  echo "  ❌ Pods not Ready after ${timeout_seconds}s — full dump:"
  kubectl get pods   -n "$namespace"
  kubectl get pvc    -n "$namespace" 2>/dev/null || true
  kubectl get events -n "$namespace" \
    --sort-by='.lastTimestamp' | tail -30
  return 1
}

# ════════════════════════════════════════
# PREREQUISITE CHECKS
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " PREREQUISITE CHECKS"
echo "══════════════════════════════════════"

PREREQ_FAILED=0

echo "==> Checking SQS queue: ${CLUSTER_NAME}-karpenter"
SQS_URL=$(aws sqs get-queue-url \
  --queue-name "${CLUSTER_NAME}-karpenter" \
  --region "$REGION" \
  --query 'QueueUrl' \
  --output text 2>/dev/null || echo "MISSING")

if [[ "$SQS_URL" == "MISSING" ]]; then
  echo "  ❌ SQS queue ${CLUSTER_NAME}-karpenter NOT FOUND"
  PREREQ_FAILED=1
else
  echo "  ✅ SQS queue exists: $SQS_URL"
fi

echo "==> Checking IAM instance profile: ${CLUSTER_NAME}-karpenter-node"
PROFILE_ARN=$(aws iam get-instance-profile \
  --instance-profile-name "${CLUSTER_NAME}-karpenter-node" \
  --query 'InstanceProfile.Arn' \
  --output text 2>/dev/null || echo "MISSING")

if [[ "$PROFILE_ARN" == "MISSING" ]]; then
  echo "  ❌ Instance profile ${CLUSTER_NAME}-karpenter-node NOT FOUND"
  PREREQ_FAILED=1
else
  echo "  ✅ Instance profile exists: $PROFILE_ARN"
fi

echo "==> Checking IAM role: ${CLUSTER_NAME}-karpenter-controller"
ROLE_ARN=$(aws iam get-role \
  --role-name "${CLUSTER_NAME}-karpenter-controller" \
  --query 'Role.Arn' \
  --output text 2>/dev/null || echo "MISSING")

if [[ "$ROLE_ARN" == "MISSING" ]]; then
  echo "  ❌ IAM role ${CLUSTER_NAME}-karpenter-controller NOT FOUND"
  PREREQ_FAILED=1
else
  echo "  ✅ IAM role exists: $ROLE_ARN"
fi

echo "==> Checking Karpenter service account IRSA annotation"
SA_ROLE=$(kubectl get serviceaccount karpenter -n kube-system \
  -o jsonpath='{.metadata.annotations.eks\.amazonaws\.com/role-arn}' \
  2>/dev/null || echo "MISSING")

if [[ "$SA_ROLE" == "MISSING" || -z "$SA_ROLE" ]]; then
  echo "  ❌ Service account karpenter missing IRSA annotation"
  PREREQ_FAILED=1
else
  echo "  ✅ IRSA annotation: $SA_ROLE"
fi

if [[ "$PREREQ_FAILED" == "1" ]]; then
  echo "  ❌ Prerequisites missing — ensure stage2-apply completed then re-run"
  exit 1
fi
echo "  ✅ All prerequisites verified"

# ════════════════════════════════════════
# PATCH SQS PERMISSIONS
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " IAM PERMISSION PATCHES"
echo "══════════════════════════════════════"

SQS_QUEUE_ARN=$(aws sqs get-queue-attributes \
  --queue-url "$SQS_URL" \
  --attribute-names QueueArn \
  --query 'Attributes.QueueArn' \
  --output text)
echo "  Queue ARN: $SQS_QUEUE_ARN"

echo "==> Patching SQS permissions (idempotent)"
aws iam put-role-policy \
  --role-name "${CLUSTER_NAME}-karpenter-controller" \
  --policy-name "KarpenterSQSInterruption" \
  --policy-document "{
    \"Version\": \"2012-10-17\",
    \"Statement\": [{
      \"Sid\": \"KarpenterSQSInterruption\",
      \"Effect\": \"Allow\",
      \"Action\": [
        \"sqs:GetQueueUrl\",
        \"sqs:GetQueueAttributes\",
        \"sqs:ReceiveMessage\",
        \"sqs:DeleteMessage\"
      ],
      \"Resource\": \"${SQS_QUEUE_ARN}\"
    }]
  }"
echo "  ✅ SQS permissions patched"

# ════════════════════════════════════════
# KARPENTER
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " KARPENTER"
echo "══════════════════════════════════════"

CLUSTER_ENDPOINT=$(aws eks describe-cluster \
  --name "$CLUSTER_NAME" \
  --region "$REGION" \
  --query "cluster.endpoint" \
  --output text)
echo "  Cluster endpoint: $CLUSTER_ENDPOINT"

install_or_upgrade karpenter kube-system \
  "oci://public.ecr.aws/karpenter/karpenter" \
  --version "${KARPENTER_VERSION}" \
  --set serviceAccount.create=false \
  --set serviceAccount.name=karpenter \
  --set "settings.clusterName=${CLUSTER_NAME}" \
  --set "settings.clusterEndpoint=${CLUSTER_ENDPOINT}" \
  --set "settings.interruptionQueue=${CLUSTER_NAME}-karpenter" \
  --set "tolerations[0].key=CriticalAddonsOnly" \
  --set "tolerations[0].operator=Exists" \
  --set "tolerations[0].effect=NoSchedule" \
  --set "controller.resources.requests.cpu=100m" \
  --set "controller.resources.requests.memory=256Mi" \
  --set "controller.resources.limits.cpu=500m" \
  --set "controller.resources.limits.memory=512Mi"

echo "  Current pod status:"
kubectl get pods -n kube-system \
  -l app.kubernetes.io/name=karpenter -o wide || true

kubectl wait pod \
  -n kube-system \
  -l app.kubernetes.io/name=karpenter \
  --for=condition=Ready \
  --timeout=300s \
  && echo "  ✅ Karpenter pod Ready" \
  || {
    echo "  ❌ Karpenter pod not Ready"
    kubectl describe pod -n kube-system \
      -l app.kubernetes.io/name=karpenter
    kubectl logs -n kube-system \
      -l app.kubernetes.io/name=karpenter --tail=50 2>/dev/null || true
    exit 1
  }

echo "  Waiting 90s for Karpenter webhook to register"
sleep 90

echo "==> Deleting existing EC2NodeClass (safe — recreated immediately below)"
kubectl delete ec2nodeclass default --ignore-not-found
sleep 5

echo "==> Applying EC2NodeClass with instanceProfile"
kubectl apply -f - <<EOF
apiVersion: karpenter.k8s.aws/v1
kind: EC2NodeClass
metadata:
  name: default
spec:
  amiSelectorTerms:
    - alias: al2@latest
  instanceProfile: "${CLUSTER_NAME}-karpenter-node"
  subnetSelectorTerms:
    - tags:
        karpenter.sh/discovery: "${CLUSTER_NAME}"
  securityGroupSelectorTerms:
    - tags:
        karpenter.sh/discovery: "${CLUSTER_NAME}"
  blockDeviceMappings:
    - deviceName: /dev/xvda
      ebs:
        volumeSize: 20Gi
        volumeType: gp3
        encrypted: true
        deleteOnTermination: true
EOF

echo "==> Applying NodePool"
kubectl apply -f - <<EOF
apiVersion: karpenter.sh/v1
kind: NodePool
metadata:
  name: default
spec:
  template:
    metadata:
      annotations:
        karpenter.sh/expire-after: 720h
    spec:
      nodeClassRef:
        group: karpenter.k8s.aws
        kind: EC2NodeClass
        name: default
      requirements:
        - key: karpenter.sh/capacity-type
          operator: In
          values: ["spot", "on-demand"]
        - key: node.kubernetes.io/instance-type
          operator: In
          values: ["t3.medium", "t3a.medium", "t3.large", "t3.xlarge"]
        - key: kubernetes.io/arch
          operator: In
          values: ["amd64"]
        - key: topology.kubernetes.io/zone
          operator: In
          values: ["${REGION}a", "${REGION}b"]
  limits:
    cpu: "16"
    memory: 32Gi
  disruption:
    consolidationPolicy: WhenEmptyOrUnderutilized
    consolidateAfter: 30s
EOF

echo "  EC2NodeClass + NodePool applied"

echo "==> Waiting for EC2NodeClass Ready=True (max 3 min)"
EC2_READY=false
for i in $(seq 1 18); do
  IP_STATUS=$(kubectl get ec2nodeclass default \
    -o jsonpath='{.status.conditions[?(@.type=="InstanceProfileReady")].status}' \
    2>/dev/null || echo "Unknown")
  NC_STATUS=$(kubectl get ec2nodeclass default \
    -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' \
    2>/dev/null || echo "Unknown")
  echo "  [$(( i * 10 ))s] InstanceProfileReady=${IP_STATUS}  Ready=${NC_STATUS}"
  if [[ "$NC_STATUS" == "True" ]]; then
    echo "  ✅ EC2NodeClass Ready — Karpenter can provision nodes"
    EC2_READY=true
    break
  fi
  sleep 10
done

if [[ "$EC2_READY" == "false" ]]; then
  echo "  ❌ EC2NodeClass not Ready after 3 min"
  kubectl describe ec2nodeclass default 2>/dev/null || true
  kubectl logs -n kube-system \
    -l app.kubernetes.io/name=karpenter --tail=30 2>/dev/null || true
  exit 1
fi

kubectl get nodepool default 2>/dev/null || true
echo "  Pausing 20s for NodePool to reach Ready"
sleep 20

# ════════════════════════════════════════
# STORAGE PREREQUISITES
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " STORAGE PREREQUISITES"
echo "══════════════════════════════════════"

echo "==> Verifying EBS CSI driver"
kubectl wait pod \
  -n kube-system \
  -l app.kubernetes.io/name=aws-ebs-csi-driver \
  --for=condition=Ready \
  --timeout=120s \
  && echo "  ✅ EBS CSI driver Ready" \
  || kubectl get pods -n kube-system | grep ebs \
  || echo "  ❌ No EBS CSI pods found"

echo "==> Ensuring gp3 StorageClass exists"
if kubectl get storageclass gp3 &>/dev/null; then
  echo "  ✅ gp3 StorageClass already exists"
else
  kubectl apply -f - <<EOF
apiVersion: storage.k8s.io/v1
kind: StorageClass
metadata:
  name: gp3
  annotations:
    storageclass.kubernetes.io/is-default-class: "true"
provisioner: ebs.csi.aws.com
parameters:
  type: gp3
  encrypted: "true"
volumeBindingMode: WaitForFirstConsumer
reclaimPolicy: Retain
allowVolumeExpansion: true
EOF
  echo "  ✅ gp3 StorageClass created"
fi

kubectl patch storageclass gp2 \
  -p '{"metadata":{"annotations":{"storageclass.kubernetes.io/is-default-class":"false"}}}' \
  2>/dev/null && echo "  ✅ gp2 default annotation removed" \
  || echo "  gp2 not present or already non-default"

echo "==> StorageClasses:"
kubectl get storageclass

# ════════════════════════════════════════
# NODE CAPACITY CHECK
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " NODE CAPACITY CHECK"
echo "══════════════════════════════════════"

kubectl get nodes -o custom-columns=\
"NAME:.metadata.name,\
STATUS:.status.conditions[-1].type,\
CPU:.status.allocatable.cpu,\
MEM:.status.allocatable.memory,\
ZONE:.metadata.labels.topology\.kubernetes\.io/zone"

echo ""
aws ec2 describe-subnets \
  --region "$REGION" \
  --filters "Name=tag:karpenter.sh/discovery,Values=${CLUSTER_NAME}" \
  --query 'Subnets[].{ID:SubnetId,AZ:AvailabilityZone,CIDR:CidrBlock}' \
  --output table 2>/dev/null \
  || echo "  ⚠️  No subnets tagged karpenter.sh/discovery=${CLUSTER_NAME}"

aws ec2 describe-security-groups \
  --region "$REGION" \
  --filters "Name=tag:karpenter.sh/discovery,Values=${CLUSTER_NAME}" \
  --query 'SecurityGroups[].{ID:GroupId,Name:GroupName}' \
  --output table 2>/dev/null \
  || echo "  ⚠️  No SGs tagged karpenter.sh/discovery=${CLUSTER_NAME}"

# ════════════════════════════════════════
# NAMESPACE CLEANUP
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " NAMESPACE CLEANUP"
echo "══════════════════════════════════════"

echo "==> Uninstalling all previous Helm releases in $OBS_NAMESPACE"
for release in kube-prometheus-stack elasticsearch kibana \
               otel-collector jaeger fluent-bit; do
  STATUS=$(helm status "$release" -n "$OBS_NAMESPACE" \
    --output json 2>/dev/null \
    | python3 -c "import sys,json; \
        print(json.load(sys.stdin)['info']['status'])" \
    2>/dev/null || echo "not-found")
  if [[ "$STATUS" != "not-found" ]]; then
    echo "  Uninstalling $release (was: $STATUS)"
    helm uninstall "$release" -n "$OBS_NAMESPACE" --ignore-not-found
  else
    echo "  $release — not installed, skipping"
  fi
done

echo "==> Deleting all PVCs in $OBS_NAMESPACE"
PVC_COUNT=$(kubectl get pvc -n "$OBS_NAMESPACE" \
  --no-headers 2>/dev/null | wc -l | tr -d ' ')
if [[ "$PVC_COUNT" -gt "0" ]]; then
  echo "  Found $PVC_COUNT PVC(s) — deleting"
  kubectl delete pvc --all -n "$OBS_NAMESPACE" 2>/dev/null || true
  echo "  ✅ PVCs deleted"
else
  echo "  No PVCs found — namespace is clean"
fi

echo "==> Waiting 10s for cleanup to propagate"
sleep 10

echo "==> Namespace state after cleanup:"
kubectl get all -n "$OBS_NAMESPACE" 2>/dev/null || echo "  namespace is empty"

# ════════════════════════════════════════
# OBSERVABILITY STACK
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " OBSERVABILITY STACK"
echo "══════════════════════════════════════"

kubectl create namespace "$OBS_NAMESPACE" \
  --dry-run=client -o yaml | kubectl apply -f -

echo "==> Deploying kube-prometheus-stack"
helm install kube-prometheus-stack \
  prometheus-community/kube-prometheus-stack \
  -n "$OBS_NAMESPACE" \
  --version 58.2.2 \
  --timeout 30m \
  --set prometheusOperator.admissionWebhooks.enabled=false \
  --set prometheusOperator.admissionWebhooks.patch.enabled=false \
  --set "grafana.adminPassword=${GRAFANA_PASSWORD}" \
  --set grafana.persistence.enabled=true \
  --set grafana.persistence.storageClassName=gp3 \
  --set prometheus.prometheusSpec.storageSpec.volumeClaimTemplate.spec.storageClassName=gp3 \
  --set prometheus.prometheusSpec.retention=30d
wait_for_pods "$OBS_NAMESPACE" "kube-prometheus-stack" 1800

echo "==> Deploying elasticsearch"
helm install elasticsearch \
  elastic/elasticsearch \
  -n "$OBS_NAMESPACE" \
  --version 8.5.1 \
  --timeout 15m \
  --set replicas=1 \
  --set minimumMasterNodes=1 \
  --set esJavaOpts="-Xmx512m -Xms512m" \
  --set volumeClaimTemplate.storageClassName=gp3 \
  --set "esConfig.elasticsearch\\.yml=xpack.security.enabled: false\nxpack.ml.enabled: false\n"
wait_for_pods "$OBS_NAMESPACE" "elasticsearch" 900

echo "==> Deploying kibana"
helm install kibana \
  elastic/kibana \
  -n "$OBS_NAMESPACE" \
  --version 8.5.1 \
  --timeout 10m \
  --set "elasticsearchHosts=http://elasticsearch-master.${OBS_NAMESPACE}.svc.cluster.local:9200"
wait_for_pods "$OBS_NAMESPACE" "kibana" 600

echo "==> Deploying otel-collector"
helm install otel-collector \
  open-telemetry/opentelemetry-collector \
  -n "$OBS_NAMESPACE" \
  --version 0.91.0 \
  --timeout 5m \
  --set mode=deployment \
  --set image.repository=otel/opentelemetry-collector-contrib
wait_for_pods "$OBS_NAMESPACE" "otel-collector" 300

echo "==> Deploying jaeger"
helm install jaeger \
  jaegertracing/jaeger \
  -n "$OBS_NAMESPACE" \
  --version 3.0.0 \
  --timeout 5m \
  --set provisionDataStore.cassandra=false \
  --set provisionDataStore.elasticsearch=false \
  --set storage.type=elasticsearch \
  --set "storage.elasticsearch.host=elasticsearch-master.${OBS_NAMESPACE}.svc.cluster.local" \
  --set storage.elasticsearch.port=9200 \
  --set agent.enabled=false
wait_for_pods "$OBS_NAMESPACE" "jaeger" 300

echo "==> Deploying fluent-bit"
helm install fluent-bit \
  fluent/fluent-bit \
  -n "$OBS_NAMESPACE" \
  --version 0.46.7 \
  --timeout 5m
wait_for_pods "$OBS_NAMESPACE" "fluent-bit" 300

# ════════════════════════════════════════
# SUMMARY
# ════════════════════════════════════════
echo ""
echo "══════════════════════════════════════"
echo " DEPLOYMENT COMPLETE"
echo "══════════════════════════════════════"
echo ""
echo "Karpenter:"
helm status karpenter -n kube-system --output json \
  | python3 -c "import sys,json; \
      print('  status:', json.load(sys.stdin)['info']['status'])"

echo ""
echo "Observability:"
for release in kube-prometheus-stack elasticsearch kibana \
               otel-collector jaeger fluent-bit; do
  STATUS=$(helm status "$release" -n "$OBS_NAMESPACE" \
    --output json 2>/dev/null \
    | python3 -c "import sys,json; \
        print(json.load(sys.stdin)['info']['status'])" \
    2>/dev/null || echo "not-found")
  printf "  %-30s %s\n" "$release" "$STATUS"
done

echo ""
echo "Nodes:"
kubectl get nodes --no-headers \
  | awk '{printf "  %-40s %s\n", $1, $2}'

echo ""
echo "PVCs:"
kubectl get pvc -n "$OBS_NAMESPACE" 2>/dev/null || echo "  none"

echo ""
echo "Pods:"
kubectl get pods -n "$OBS_NAMESPACE" --no-headers \
  | awk '{printf "  %-50s %-15s %s\n", $1, $3, $2}'
echo ""
